import type { ExpectedResult, RuleCheckPlan } from '../checkPlan'
import { containsOdvPlaceholder } from '../odv'
import type { IntuneDataType } from '../operatorMap'

const HEADER_LINES = [
  '#!/bin/bash',
  '# Intune custom compliance discovery script for macOS, generated by intune-compliance-toolkit.',
  '# Prints one compact JSON object keyed by Intune SettingName. Runs as root, like mSCP.',
  '# Checks come from the NIST macOS Security Compliance Project',
  '# (https://github.com/usnistgov/macos_security), licensed CC BY 4.0',
  '# (https://creativecommons.org/licenses/by/4.0/). Content modified by this project.',
  '# Outer script: bash 3.2 compatible. Each check runs under zsh, as in mSCP.',
  '',
  '# ICT_TEST_ARCH, ICT_TEST_OS_MAJOR and ICT_TEST_CHECK_SHELL exist only so',
  '# tests can execute this script without a Mac or zsh.',
  '',
]

// mSCP's compliance_script.sh.jinja variable block. Exported because checks
// run in a separate zsh process, not in this shell.
const PREAMBLE_LINES = [
  'plb="/usr/libexec/PlistBuddy"',
  'CURRENT_USER=$( /usr/bin/defaults read /Library/Preferences/com.apple.loginwindow lastUserName 2>/dev/null )',
  'CURR_USER_UID=$(/usr/bin/id -u $CURRENT_USER)',
  'CURR_HOSTNAME=$(/usr/sbin/scutil --get HostName 2>/dev/null)',
  'arch=${ICT_TEST_ARCH:-$(/usr/bin/arch)}',
  'export plb CURRENT_USER CURR_USER_UID CURR_HOSTNAME arch',
  '',
  '__os_major=${ICT_TEST_OS_MAJOR:-$(/usr/bin/sw_vers -productVersion 2>/dev/null | /usr/bin/cut -d. -f1)}',
  '',
  '# A compliance tool must not report compliant when it cannot tell which',
  '# checks apply, so an unknown OS version reports null (non-compliant) for every rule.',
  '__os_major_known=true',
  'case "$__os_major" in',
  "  ''|*[!0-9]*) __os_major_known=false ;;",
  'esac',
  '',
  "# Discards stderr like mSCP's run_scan() { ... } 2>/dev/null.",
  '__run_check() {',
  '  if [ -n "${ICT_TEST_CHECK_SHELL:-}" ]; then',
  '    "$ICT_TEST_CHECK_SHELL" -c "$1" 2>/dev/null',
  '  else',
  '    /bin/zsh --no-rcs -c "$1" 2>/dev/null',
  '  fi',
  '}',
  '',
]

// No jq on managed Macs, so JSON encoding is done here. Replacement strings
// are held in variables and double-quoted so bash 3.2 and bash 5.2+
// (patsub_replacement) both insert them literally. Verified in bash.test.ts.
const JSON_HELPER_LINES = [
  "__JSON_NEWLINE=$'\\n'",
  "__JSON_RETURN=$'\\r'",
  "__JSON_TAB=$'\\t'",
  "__JSON_ESCAPED_BACKSLASH='\\\\'",
  "__JSON_ESCAPED_QUOTE='\\\"'",
  "__JSON_ESCAPED_NEWLINE='\\n'",
  "__JSON_ESCAPED_RETURN='\\r'",
  "__JSON_ESCAPED_TAB='\\t'",
  '',
  '__json_bool() {',
  '  case "$1" in',
  "    true) printf 'true' ;;",
  "    false) printf 'false' ;;",
  "    *) printf 'null' ;;",
  '  esac',
  '}',
  '',
  '# Only canonical JSON integers (0 or -?[1-9][0-9]*); anything else is null.',
  '__json_int() {',
  '  case "${1#-}" in',
  "    ''|*[!0-9]*|0?*) printf 'null' ;;",
  "    0) if [ \"$1\" = '0' ]; then printf '0'; else printf 'null'; fi ;;",
  "    *) printf '%s' \"$1\" ;;",
  '  esac',
  '}',
  '',
  '__json_escape_control_characters() {',
  '  local value=$1 octal character replacement',
  '  for octal in 001 002 003 004 005 006 007 010 013 014 016 017 020 021 022 023 024 025 026 027 030 031 032 033 034 035 036 037; do',
  "    printf -v character \"\\\\$octal\"",
  "    printf -v replacement '\\\\u%04x' \"0$octal\"",
  '    value=${value//$character/"$replacement"}',
  '  done',
  "  printf '%s' \"$value\"",
  '}',
  '',
  '__json_str() {',
  '  if [ -z "$1" ]; then',
  "    printf 'null'",
  '    return',
  '  fi',
  '  local value=$1',
  "  value=${value//\\\\/\"$__JSON_ESCAPED_BACKSLASH\"}",
  "  value=${value//\\\"/\"$__JSON_ESCAPED_QUOTE\"}",
  '  value=${value//$__JSON_NEWLINE/"$__JSON_ESCAPED_NEWLINE"}',
  '  value=${value//$__JSON_RETURN/"$__JSON_ESCAPED_RETURN"}',
  '  value=${value//$__JSON_TAB/"$__JSON_ESCAPED_TAB"}',
  '  case "$value" in',
  '    *[[:cntrl:]]*) value=$(__json_escape_control_characters "$value") ;;',
  '  esac',
  "  printf '\"%s\"' \"$value\"",
  '}',
]

const SETTING_NAME_PATTERN = /^[A-Za-z0-9_]+$/
const MAJOR_VERSION_PATTERN = /^[0-9]+$/
const FIRST_PRINTABLE_CODE = 0x20
const DELETE_CODE = 0x7f

// Keeps a title on its comment line: a newline in it would end the comment.
function singleLineComment(text: string): string {
  return Array.from(text, (character) => {
    const code = character.charCodeAt(0)
    return code < FIRST_PRINTABLE_CODE || code === DELETE_CODE ? ' ' : character
  }).join('')
}

// The standard shell idiom: end the quote, insert an escaped quote, resume.
export function bashSingleQuote(text: string): string {
  return `'${text.replaceAll("'", "'\\''")}'`
}

function resultVariable(plan: RuleCheckPlan): string {
  return `__result_${plan.settingName}`
}

function jsonHelperFor(dataType: IntuneDataType): string {
  if (dataType === 'Int64') return '__json_int'
  if (dataType === 'Boolean') return '__json_bool'
  return '__json_str'
}

function assertMajor(major: string, plan: RuleCheckPlan): void {
  if (!MAJOR_VERSION_PATTERN.test(major)) throw new Error(`${plan.id}: "${major}" is not a macOS major version.`)
}

function assertPlanIsSafe(plan: RuleCheckPlan): void {
  if (!SETTING_NAME_PATTERN.test(plan.settingName)) {
    throw new Error(`${plan.id}: SettingName "${plan.settingName}" must contain only letters, digits and underscores.`)
  }
  assertMajor(plan.newerThan, plan)
  const checks = [...plan.branches, ...(plan.newerBranch ? [plan.newerBranch] : [])]
  for (const check of checks) {
    if (containsOdvPlaceholder(check.shell) && plan.exportedOdv === null) {
      throw new Error(`${plan.id}: a check shell still contains $ODV.`)
    }
    if (typeof check.expected.value === 'string' && containsOdvPlaceholder(check.expected.value)) {
      throw new Error(`${plan.id}: an expected value still contains $ODV.`)
    }
  }
  for (const branch of plan.branches) branch.majors.forEach((major) => assertMajor(major, plan))
}

function checkLines(plan: RuleCheckPlan, shell: string, expected: ExpectedResult): string[] {
  const variable = resultVariable(plan)
  const exportOdv = plan.exportedOdv === null ? '' : `export ODV=${bashSingleQuote(plan.exportedOdv)} ; `
  // The trailing newline matches mSCP's `$( check\n)`, e.g. for a heredoc
  // terminator on the check's last line.
  const lines = [`  ${variable}=$( ${exportOdv}__run_check ${bashSingleQuote(`${shell}\n`)} )`]
  if (plan.reporting === 'boolean') {
    lines.push(
      `  if [ "$${variable}" = ${bashSingleQuote(String(expected.value))} ]; then ${variable}='true'; else ${variable}='false'; fi`,
    )
  }
  return lines
}

function ruleLines(plan: RuleCheckPlan): string[] {
  const variable = resultVariable(plan)
  const passValue = plan.reporting === 'raw' ? String(plan.operand) : 'true'
  // An empty result is reported as null by every JSON helper.
  const lines = [
    `# --- ${singleLineComment(`${plan.id}: ${plan.title}`)} ---`,
    `${variable}=''`,
    `if [ "$__os_major_known" = 'true' ]; then ${variable}=${bashSingleQuote(passValue)}; fi`,
  ]

  const dispatch: string[] = []
  plan.branches.forEach((branch, index) => {
    const keyword = index === 0 ? 'if' : 'elif'
    const condition = branch.majors.map((major) => `[ "$__os_major" = ${bashSingleQuote(major)} ]`).join(' || ')
    dispatch.push(`${keyword} ${condition}; then`, ...checkLines(plan, branch.shell, branch.expected))
  })
  if (plan.newerBranch) {
    const keyword = dispatch.length === 0 ? 'if' : 'elif'
    dispatch.push(
      `${keyword} [ "$__os_major" -gt ${plan.newerThan} ] 2>/dev/null; then`,
      ...checkLines(plan, plan.newerBranch.shell, plan.newerBranch.expected),
    )
  }
  if (dispatch.length > 0) dispatch.push('fi')

  if (plan.architecture) {
    lines.push(`if [ "$arch" = ${bashSingleQuote(plan.architecture)} ]; then`, ...dispatch.map((line) => `  ${line}`), 'fi')
  } else {
    lines.push(...dispatch)
  }
  lines.push('')
  return lines
}

function outputLine(plans: RuleCheckPlan[]): string {
  const format = plans.map((plan) => `"${plan.settingName}":%s`).join(',')
  const values = plans.map((plan) => ` "$(${jsonHelperFor(plan.dataType)} "$${resultVariable(plan)}")"`).join('')
  return `printf '{${format}}\\n'${values}`
}

export function generateBashScript(plans: RuleCheckPlan[]): string {
  const seenSettingNames = new Set<string>()
  for (const plan of plans) {
    assertPlanIsSafe(plan)
    if (seenSettingNames.has(plan.settingName)) throw new Error(`Duplicate SettingName "${plan.settingName}".`)
    seenSettingNames.add(plan.settingName)
  }

  const lines = [...HEADER_LINES, ...PREAMBLE_LINES, ...JSON_HELPER_LINES, '']
  for (const plan of plans) lines.push(...ruleLines(plan))
  lines.push(outputLine(plans), 'exit 0')
  return lines.join('\n') + '\n'
}
